/* === inscription.js === */

const LOGO_B64 = "data:image/png;base64,";


function switchTab(id) {
  document.querySelectorAll(".form-panel").forEach(p => p.classList.remove("active"));
  document.querySelectorAll(".inscription-tab").forEach(t => t.classList.remove("active"));
  document.getElementById("form-" + id).classList.add("active");
  document.getElementById("tab-" + id).classList.add("active");
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function selectTarif(form, card) {
  const panelId = "form-" + (form === "j" ? "jeunes" : "seniors");
  document.getElementById(panelId).querySelectorAll(".tarif-card").forEach(c => c.classList.remove("selected"));
  card.classList.add("selected");
  const radio = card.querySelector("input[type=radio]");
  if (radio) radio.checked = true;
}

const canvases = {};

function initCanvas(prefix) {
  const canvas = document.getElementById(prefix + "_canvas");
  const hint   = document.getElementById(prefix + "_hint");
  if (!canvas) return;
  const dpr = window.devicePixelRatio || 1;
  const w = canvas.offsetWidth || canvas.closest(".inscription-main")?.offsetWidth || 860;
  canvas.width  = w * dpr;
  canvas.height = 130 * dpr;
  const ctx = canvas.getContext("2d");
  ctx.scale(dpr, dpr);
  ctx.strokeStyle = "#223224";
  ctx.lineWidth   = 2.4;
  ctx.lineCap     = "round";
  ctx.lineJoin    = "round";
  canvases[prefix] = { canvas, hint, ctx, drawing: false, hasContent: false };

  const pos = (e) => {
    const r = canvas.getBoundingClientRect();
    const src = e.touches ? e.touches[0] : e;
    return { x: src.clientX - r.left, y: src.clientY - r.top };
  };
  const start = (e) => {
    e.preventDefault();
    const p = pos(e);
    canvases[prefix].drawing = true;
    canvases[prefix].ctx.beginPath();
    canvases[prefix].ctx.moveTo(p.x, p.y);
    hint.style.opacity = "0";
    canvases[prefix].hasContent = true;
  };
  const move = (e) => {
    e.preventDefault();
    if (!canvases[prefix].drawing) return;
    const p = pos(e);
    canvases[prefix].ctx.lineTo(p.x, p.y);
    canvases[prefix].ctx.stroke();
  };
  const stop = () => { canvases[prefix].drawing = false; };

  canvas.addEventListener("mousedown",  start);
  canvas.addEventListener("mousemove",  move);
  canvas.addEventListener("mouseup",    stop);
  canvas.addEventListener("mouseleave", stop);
  canvas.addEventListener("touchstart", start, { passive: false });
  canvas.addEventListener("touchmove",  move,  { passive: false });
  canvas.addEventListener("touchend",   stop);
}

function clearCanvas(prefix) {
  const { canvas, ctx, hint } = canvases[prefix];
  const dpr = window.devicePixelRatio || 1;
  ctx.clearRect(0, 0, canvas.width / dpr, canvas.height / dpr);
  hint.style.opacity = "1";
  canvases[prefix].hasContent = false;
}

function getSignatureDataURL(prefix) {
  const c = canvases[prefix];
  return c && c.hasContent ? c.canvas.toDataURL("image/png") : null;
}

document.addEventListener("inscriptionLoaded", () => {
  initCanvas("j");
  initCanvas("s");
});

function v(id) { return (document.getElementById(id) || {}).value || ""; }
function radioVal(name) {
  const el = document.querySelector('input[name="' + name + '"]:checked');
  return el ? el.value : "---";
}

function generatePDF(type) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });

  const VD  = [34,  50,  36];
  const VS  = [6,   62,  11];
  const VP  = [172, 194, 171];
  const VL  = [243, 246, 243];
  const BL  = [255, 255, 255];
  const GR  = [170, 170, 170];

  const M = 12, CW = 186;
  let y = M;

  doc.addImage(LOGO_B64, "PNG", M, y, 16, 21);
  doc.setFontSize(15); doc.setFont("helvetica", "bold"); doc.setTextColor(...VS);
  doc.text("VOLLEY BALL OLLIOULAIS", M + 20, y + 8);
  doc.setFontSize(9); doc.setFont("helvetica", "normal"); doc.setTextColor(...VD);
  doc.text(type === "jeunes"
    ? "FICHE DE RENSEIGNEMENTS JEUNES - SAISON 2026-2027"
    : "FICHE DE RENSEIGNEMENTS SENIORS - SAISON 2026-2027", M + 20, y + 14);
  doc.setDrawColor(...VD); doc.setLineWidth(0.3); doc.rect(210 - M - 22, y, 22, 21);
  doc.setFontSize(6); doc.setTextColor(150, 150, 150);
  doc.text("[ QR Code\nHelloAsso ]", 210 - M - 11, y + 8, { align: "center" });
  y += 25;

  const band = (txt) => {
    doc.setFillColor(...VS); doc.rect(M, y, CW, 7, "F");
    doc.setFontSize(8); doc.setFont("helvetica", "bold"); doc.setTextColor(...BL);
    doc.text(txt, M + 3, y + 5); y += 9;
  };

  const field = (lbl, val, x, fw, ly) => {
    doc.setFontSize(6.5); doc.setFont("helvetica", "bold"); doc.setTextColor(...VS);
    doc.text(lbl, x, ly - 3.5);
    doc.setFont("helvetica", "normal"); doc.setFontSize(9); doc.setTextColor(...VD);
    if (val) doc.text(val, x, ly - 0.5);
    doc.setDrawColor(...GR); doc.setLineWidth(0.25); doc.line(x, ly + 0.5, x + fw, ly + 0.5);
  };

  const t3W = CW / 3;
  const catDefs = type === "jeunes"
    ? [{ id:"j_m7",  lbl:"M7 - Baby Volley", ann:"Ne en 2020-2021+",     prix:"140+47 EUR (maillot+short)", ch:"2 cheques" },
       { id:"j_m9",  lbl:"M9 a M15",          ann:"Ne entre 2012-2019",    prix:"160+47 EUR (maillot+short)", ch:"2 cheques" },
       { id:"j_m18", lbl:"M18 et M21",         ann:"Ne entre 2006-2011",    prix:"190+47 EUR (maillot+short)", ch:"2 cheques" }]
    : [{ id:"s_comp",   lbl:"Seniors",         ann:"Ne en 2005 et avant", prix:"200+47 EUR (maillot+short)", ch:"2 cheques" },
       { id:"s_loisirs",lbl:"Seniors Loisirs", ann:"",                    prix:"100+47 EUR (maillot+short)", ch:"Maillot non oblig." },
       { id:"s_lib",    lbl:"Compet Lib",       ann:"",                    prix:"130+47 EUR (maillot+short)", ch:"Maillot non oblig." }];

  catDefs.forEach((cat, i) => {
    const x = M + i * t3W, sel = document.getElementById(cat.id)?.checked;
    doc.setFillColor(...(sel ? VS : VD)); doc.rect(x, y, t3W, 9, "F");
    doc.setDrawColor(...VD); doc.setLineWidth(0.3); doc.rect(x, y, t3W, 9);
    doc.setFontSize(8); doc.setFont("helvetica", "bold"); doc.setTextColor(...VP);
    doc.text((sel ? "[X] " : "[ ] ") + cat.lbl, x + 3, y + 6);
    doc.setFillColor(...VL); doc.rect(x, y + 9, t3W, 14, "F"); doc.rect(x, y + 9, t3W, 14);
    doc.setFontSize(6.5); doc.setFont("helvetica", "normal"); doc.setTextColor(80, 80, 80);
    if (cat.ann) doc.text(cat.ann, x + 3, y + 14);
    doc.setFont("helvetica", "bold"); doc.setFontSize(7.5); doc.setTextColor(...VD);
    doc.text(cat.prix, x + 3, cat.ann ? y + 18.5 : y + 14);
    doc.setFont("helvetica", "normal"); doc.setFontSize(6.5); doc.setTextColor(100, 100, 100);
    doc.text(cat.ch, x + 3, cat.ann ? y + 22 : y + 18);
  });
  y += 26;

  const lW = CW * 0.60, rW = CW * 0.40, yId = y, fh = 9;

  if (type === "jeunes") {
    band("IDENTITE DU LICENCIE");
    const hW = lW / 2;
    field("NOM", v("j_nom").toUpperCase(), M, hW-2, y); field("PRENOM", v("j_prenom"), M+hW, hW-2, y); y+=fh;
    field("DATE DE NAISSANCE", v("j_ddn"), M, hW-2, y); field("NATIONALITE", v("j_nat"), M+hW, hW-2, y); y+=fh;
    field("TELEPHONE", v("j_tel"), M, hW-2, y); field("EMAIL", v("j_email"), M+hW, hW-2, y); y+=fh;
    field("ADRESSE", v("j_adresse"), M, lW-2, y); y+=fh;
    const vW=lW*.46,tW=lW*.27,sW=lW-vW-tW;
    field("CP/VILLE",v("j_ville"),M,vW-2,y); field("MAILLOT",v("j_tshirt"),M+vW,tW-2,y); field("SHORT",v("j_short"),M+vW+tW,sW-2,y); y+=fh;
    band("RESPONSABLE LEGAL");
    field("NOM ET PRENOM", v("j_rl_nom"), M, lW-2, y); y+=fh;
    field("TEL.PERE",v("j_tel_pere"),M,hW-2,y); field("EMAIL PERE",v("j_email_pere"),M+hW,hW-2,y); y+=fh;
    field("TEL.MERE",v("j_tel_mere"),M,hW-2,y); field("EMAIL MERE",v("j_email_mere"),M+hW,hW-2,y); y+=fh;
  } else {
    band("IDENTITE DU LICENCIE");
    const hW = lW / 2;
    field("NOM",v("s_nom").toUpperCase(),M,hW-2,y); field("PRENOM",v("s_prenom"),M+hW,hW-2,y); y+=fh;
    field("DATE NAISSANCE",v("s_ddn"),M,hW-2,y); field("NATIONALITE",v("s_nat"),M+hW,hW-2,y); y+=fh;
    field("ADRESSE",v("s_adresse"),M,lW-2,y); y+=fh;
    field("CODE POSTAL/VILLE",v("s_ville"),M,lW-2,y); y+=fh;
    field("TELEPHONE",v("s_tel"),M,hW-2,y); field("EMAIL",v("s_email"),M+hW,hW-2,y); y+=fh;
    const tW2=lW/2;
    field("TAILLE MAILLOT",v("s_tshirt"),M,tW2-2,y); field("TAILLE SHORT",v("s_short"),M+tW2,tW2-2,y); y+=fh;
    doc.setFontSize(7.5); doc.setFont("helvetica","normal"); doc.setTextColor(...VD);
    doc.text("Formation arbitre/marqueur : "+radioVal("s_arb")+"   |   Formation entraineur : "+radioVal("s_ent"),M,y); y+=8;
  }

  const cX=M+lW+3, cW3=rW-5, cy0=yId;
  doc.setFillColor(...VS); doc.rect(cX,cy0,cW3,7,"F");
  doc.setFontSize(7); doc.setFont("helvetica","bold"); doc.setTextColor(...BL);
  doc.text("CADRE RESERVE AU CLUB",cX+2,cy0+5);
  doc.setDrawColor(...VD); doc.setLineWidth(0.3); doc.rect(cX,cy0+9,cW3,50);
  doc.setFontSize(8.5); doc.setFont("helvetica","normal"); doc.setTextColor(...VD);
  doc.text("[ ] RENOUVELLEMENT",cX+3,cy0+18);
  doc.text("[ ] CREATION",cX+3,cy0+27);
  doc.text("[ ] MUTATION",cX+3,cy0+36);
  doc.setDrawColor(...GR); doc.setLineWidth(0.2); doc.setFontSize(7);
  doc.text("Type :",cX+3,cy0+44); doc.line(cX+3,cy0+45,cX+cW3-3,cy0+45);
  doc.text("N licence :",cX+3,cy0+51); doc.line(cX+3,cy0+52,cX+cW3-3,cy0+52);
  doc.text("Homologue le :",cX+3,cy0+58); doc.line(cX+3,cy0+59,cX+cW3-3,cy0+59);
  y=Math.max(y,cy0+62);

  const hCW=CW/2;
  band("PIECES A FOURNIR");
  const pc=["La presente fiche de renseignement","Cotisation par cheque (echelonnable) + cheque 47 EUR maillot a l ordre de : Volley Ball Ollioulais ou paiement HelloAsso","Le formulaire de demande de licence complete","Certificat medical si QS non OK"];
  const pn=type==="jeunes"?[...pc,"1 photo d identite","Photocopie carte d identite ou livret famille"]:[...pc,"1 photo d identite","Photocopie de la carte d identite"];
  doc.setFillColor(...VP); doc.rect(M,y,hCW,7,"F"); doc.rect(M+hCW,y,hCW,7,"F");
  doc.setDrawColor(...VD); doc.rect(M,y,hCW,7); doc.rect(M+hCW,y,hCW,7);
  doc.setFontSize(7); doc.setFont("helvetica","bold"); doc.setTextColor(...VS);
  doc.text("Licencie saison 2025/2026 au VBO",M+2,y+5); doc.text("Nouveau licencie",M+hCW+2,y+5);
  y+=7;
  const pyS=y; let p1=y+4, p2=y+4;
  doc.setFont("helvetica","normal"); doc.setFontSize(6.5); doc.setTextColor(40,40,40);
  pc.forEach(p=>{ const l=doc.splitTextToSize("- "+p,hCW-6); doc.text(l,M+3,p1); p1+=l.length*3.5+1; });
  pn.forEach(p=>{ const l=doc.splitTextToSize("- "+p,hCW-6); doc.text(l,M+hCW+3,p2); p2+=l.length*3.5+1; });
  const pyE=Math.max(p1,p2)+2;
  doc.setDrawColor(...VD); doc.setLineWidth(0.3); doc.rect(M,pyS,hCW,pyE-pyS); doc.rect(M+hCW,pyS,hCW,pyE-pyS);
  y=pyE;

  if(type==="jeunes"){
    band("AUTORISATIONS");
    const auts=[{id:"j_aut1",t:"J autorise mon enfant a participer aux entrainements, matchs et deplacements organises par le club."},{id:"j_aut2",t:"J autorise le club a prendre toute disposition medicale en cas d accident."},{id:"j_aut3",t:"J autorise l utilisation de l image de mon enfant dans le cadre des activites du club, sauf opposition ecrite."},{id:"j_aut4",t:"J autorise l utilisation des donnees personnelles de mon enfant pour la gestion interne du club."}];
    doc.setFont("helvetica","normal"); doc.setFontSize(7.5); doc.setTextColor(...VD);
    auts.forEach(a=>{ const chk=document.getElementById(a.id)?.checked; const l=doc.splitTextToSize((chk?"[X] ":"[ ] ")+a.t,CW-6); doc.text(l,M+3,y); y+=l.length*3.8+1.5; });
    y+=2;
  }

  band("ENGAGEMENT");
  doc.setFont("helvetica","normal"); doc.setFontSize(7.5); doc.setTextColor(...VD);
  if(type==="jeunes"){
    const chk=document.getElementById("j_eng")?.checked;
    const l=doc.splitTextToSize((chk?"[X] ":"[ ] ")+"Je reconnais avoir pris connaissance des statuts et du reglement interieur du Volley Ball Ollioulais et les accepter sans reserve. Je comprends que l adhesion est soumise a l agrement du comite directeur.",CW-4);
    doc.text(l,M+2,y); y+=l.length*3.8+4;
  } else {
    [{id:"s_eng1",t:"Je reconnais avoir pris connaissance des statuts et du reglement interieur du Volley Ball Ollioulais et les accepter sans reserve."},{id:"s_eng2",t:"J autorise le club a utiliser mes donnees personnelles pour la gestion interne et les communications officielles."},{id:"s_eng3",t:"J autorise l utilisation de mon image sur les supports de communication du club."},{id:"s_eng4",t:"Je comprends que l adhesion est soumise a l agrement du comite directeur."}].forEach(e=>{
      const chk=document.getElementById(e.id)?.checked; const l=doc.splitTextToSize((chk?"[X] ":"[ ] ")+e.t,CW-4); doc.text(l,M+2,y); y+=l.length*3.8+1.5;
    });
    y+=3;
  }

  const fa=type==="jeunes"?v("j_fait_a"):v("s_fait_a");
  const ds=type==="jeunes"?v("j_date_sign"):v("s_date_sign");
  const sl=type==="jeunes"?"SIGNATURE DU REPRESENTANT LEGAL":"SIGNATURE DU LICENCIE";
  const sw=CW/3;
  field("FAIT A",fa,M,sw-4,y+9); field("LE",ds,M+sw,sw-4,y+9);
  doc.setFontSize(6.5); doc.setFont("helvetica","bold"); doc.setTextColor(...VS);
  doc.text(sl,M+sw*2+2,y+3);
  const sigData=getSignatureDataURL(type==="jeunes"?"j":"s");
  if(sigData){ doc.addImage(sigData,"PNG",M+sw*2,y+4,sw-2,18); }
  else { doc.setDrawColor(...GR); doc.setLineWidth(0.3); doc.rect(M+sw*2,y+4,sw-2,18); }
  y+=24;

  y+=4;
  doc.setDrawColor(180,180,180); doc.setLineWidth(0.2);
  doc.setLineDashPattern([1,1],0); doc.line(M,y,210-M,y); doc.setLineDashPattern([],0);
  y+=8;
  const fw3=CW/3;
  doc.setFontSize(7); doc.setFont("helvetica","bold"); doc.setTextColor(...VS);
  doc.text("President :",M,y); doc.text("Secretaire :",M+fw3,y); doc.text("Web :",M+fw3*2,y);
  doc.setFont("helvetica","normal"); doc.setTextColor(...VD);
  doc.text("GARRIGUES Dimitri\n06 03 89 19 71\ndimitrigarrigues@gmail.com",M,y+3.5);
  doc.text("PORTELLI Marc\n06 52 54 67 07\nsecretariatvbo@free.fr",M+fw3,y+3.5);
  doc.text("www.volleyballollioulais.fr",M+fw3*2,y+3.5);

  const nom=type==="jeunes"?(v("j_nom")||"Jeune"):(v("s_nom")||"Senior");
  doc.save("VBO_Inscription_"+nom+"_2026-2027.pdf");
}
